  const pending = claims.filter(c => c.status === 'Pending').length;
  function go(next: string) { if (next === page) return; setHistory(h => [...h, page]); setPage(next); setNotice(''); window.scrollTo(0, 0); }
  function back() { setPage(history[history.length - 1] || (role ? 'dashboard' : 'welcome')); setHistory(h => h.slice(0, -1)); setNotice(''); window.scrollTo(0, 0); }
  function switchRole() { setRole(null); setHistory([]); setPage('welcome'); setNotice(''); setPhoto(''); }
